using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            chatClient,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
            ],
            reportStorageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-reports"));
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(GreetingResponse_IsCoherentAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello! Can you introduce yourself briefly?")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        messages.Add(response);

        await scenario.EvaluateAsync(messages);
        scenario.AssertEvaluationResultsPassAllThresholds(
            new EvaluationMetricThreshold(CoherenceEvaluator.CoherenceMetricName, threshold: 3),
            new EvaluationMetricThreshold(RelevanceEvaluator.RelevanceMetricName, threshold: 3),
            new EvaluationMetricThreshold(FluencyEvaluator.FluencyMetricName, threshold: 3));
    }

    [TestMethod]
    public async Task FactualQuestion_IsRelevant()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(FactualQuestion_IsRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        messages.Add(response);

        await scenario.EvaluateAsync(messages);
        scenario.AssertEvaluationResultsPassAllThresholds(
            new EvaluationMetricThreshold(RelevanceEvaluator.RelevanceMetricName, threshold: 4));
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsCoherence()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(MultiTurnConversation_MaintainsCoherence));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan next spring.")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        messages.Add(response);

        messages.Add(new ChatMessage(ChatRole.User, "What should I pack for that trip?"));
        response = await scenario.ChatClient!.GetResponseAsync(messages);
        messages.Add(response);

        await scenario.EvaluateAsync(messages);
        scenario.AssertEvaluationResultsPassAllThresholds(
            new EvaluationMetricThreshold(CoherenceEvaluator.CoherenceMetricName, threshold: 3),
            new EvaluationMetricThreshold(RelevanceEvaluator.RelevanceMetricName, threshold: 3));
    }
}

